import os
import json
from collections import defaultdict

programs_dir = "/home/USER/runs/paper/qwen-in-glm-hpl-u1-letter/frozen/seen-3/play/users/u030/system/state/workspace/programs"
task_id = "task-2e29965a"

# Load demos
with open(os.path.join(programs_dir, task_id + ".json"), 'r') as f:
    demos = json.load(f)

def get_nonzero_colors_in_rows(grid):
    """Check if each row has at most 1 unique non-zero color."""
    for i in range(len(grid)):
        row_colors = set(c for c in grid[i] if c != 0)
        if len(row_colors) > 1:
            return False
    return True

def get_nonzero_colors_in_cols(grid):
    """Check if each column has at most 1 unique non-zero color."""
    for j in range(len(grid[0])):
        col_colors = set(c for r in grid for c in [grid[r][j]] if c != 0)
        if len(col_colors) > 1:
            return False
    return True

def try_row_pattern(grid):
    """Try row-based periodic pattern."""
    h, w = len(grid), len(grid[0])

    # Find rows with colors and their mods
    row_colors = {}
    for i in range(h):
        colors = [c for c in grid[i] if c != 0]
        if colors:
            row_colors[i] = colors[0]  # Pick first color if consistent
    row_colors_unique = set(row_colors.values())

    # Determine period from number of unique colors
    if len(row_colors_unique) <= h:
        # Try each possible period
        for p in range(1, h + 1):
            assign = {}
            valid = True
            for i, color in row_colors.items():
                k = i % p
                if k in assign and assign[k] != color:
                    valid = False
                    break
                assign[k] = color
            if valid and len(assign) <= h:
                output = [[assign[i % p] for j in range(w)] for i in range(h)]
                # Verify on input
                for i in range(h):
                    for j in range(w):
                        if grid[i][j] != 0 and output[i][j] != grid[i][j]:
                            return None  # Invalid
                return output
    return None

def try_col_pattern(grid):
    """Try column-based periodic pattern."""
    h, w = len(grid), len(grid[0])

    for p in range(1, w + 1):
        assign = {}
        valid = True
        for j in range(w):
            colors = [c for r in range(h) if grid[r][j] != 0]
            if colors:
                k = j % p
                if k in assign and assign[k] != colors[0]:
                    valid = False
                    break
                assign[k] = colors[0]
        valid = valid and len(assign) <= w
        if valid:
            assign_get = dict(assign)
            output = [[assign_get[j % p] for j in range(w)] for i in range(h)]
            # Verify
            for j in range(w):
                for i in range(h):
                    if grid[i][j] != 0 and output[i][j] != grid[i][j]:
                        return None
            return output
    return None

def try_anti_diagonal_pattern(grid):
    """Try anti-diagonal periodic pattern (i+j mod p)."""
    h, w = len(grid), len(grid[0])

    for p in range(5, 16):
        by_mod = defaultdict(list)
        for i in range(h):
            for j in range(w):
                if grid[i][j] != 0:
                    by_mod[(i+j)%p].append(grid[i][j])

        assign = {}
        valid = True
        for s_mod, colors in by_mod.items():
            c = colors[0]
            if len(set(colors)) > 1:  # Multiple different colors
                valid = False
                break
            if s_mod in assign and assign[s_mod] != c:
                valid = False
                break
            assign[s_mod] = c

        if valid and len(assign) <= min(h*w, 10):
            # Generate output
            output = [[assign.get((i+j)%p, 0) for j in range(w)] for i in range(h)]
            # Verify
            for i in range(h):
                for j in range(w):
                    if grid[i][j] != 0 and output[i][j] != grid[i][j]:
                        return None
            return output
    return None

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Try patterns in order
    if get_nonzero_colors_in_rows(grid):
        result = try_row_pattern(grid)
        if result is not None:
            return result

    if get_nonzero_colors_in_cols(grid):
        result = try_col_pattern(grid)
        if result is not None:
            return result

    result = try_anti_diagonal_pattern(grid)
    if result is not None:
        return result

    raise ValueError(f"No pattern found for {h}x{w} grid with {sum(sum(1 for c in r if c != 0) for r in grid)} colored cells")

# Test transform on demos
print("Testing transform on demos:")
for idx, demo in enumerate(demos):
    inp = demo['input']
    out_expected = demo['output']
    try:
        out_computed = transform(inp)
        if out_computed == out_expected:
            print(f"  Demo {idx+1}: PASS")
        else:
            print(f"  Demo {idx+1}: FAIL")
            errors = []
            for r in range(min(5, len(out_computed))):
                for c in range(min(5, len(out_computed[0]))):
                    if out_computed[r][c] != out_expected[r][c]:
                        errors.append(f"  ({r},{c}): got {out_computed[r][c]}, expected {out_expected[r][c]}")
            for e in errors[:5]:
                print(e)
    except Exception as e:
        print(f"  Demo {idx+1}: EXCEPTION {e}")

